41	const PROCESSING_FEE = 5;
42	
43	const FIRST_INSURANCE_PERCENT = 10;
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	// Percentages MUST go through this helper. Applying them as exact integer
55	// fractions keeps the arithmetic drift-free; the tempting `amount * 1.1`
56	// yields 110.00000000000001 for 100, and since the spec rounds premiums UP
57	// at the very end that drift becomes a whole extra G.
58	const addPercent = (amount: number, percent: number): number =>
59	  (amount * (100 + percent)) / 100;
60	
61	const BLOCK_SIZE = 3;
62	const BLOCK_BASE_PREMIUM = 60;
63	
64	const countByType = (items: Item[]): Map<string, number> => {
65	  const counts = new Map<string, number>();
66	  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
67	
68	  return counts;
69	};
70	
71	const basePremiumForType = (type: string, count: number): number =>
72	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
73	
74	const policyBasePremium = (items: Item[]): number =>
75	  [...countByType(items)]
76	    .map(([type, count]) => basePremiumForType(type, count))
77	    .reduce((total, premium) => total + premium, 0);
78	
79	const CURSE_PERCENT = 50;
80	
81	const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;
82	
83	// Every modifier is a percentage of a base premium, and they are SUMMED rather
84	// than compounded: the spec's worked example reads
85	// "100 G base + 50 G curse + 10 G first insurance = 160 G + 5 G fee = 165 G",
86	// so the first-insurance 10 % is taken on the policy base, not on the
87	// curse-inflated amount.
88	const itemSurcharges = (items: Item[]): number =>
89	  items
90	    .filter((item) => item.cursed)
91	    .reduce((total, item) => total + percentOf(BASE_PREMIUMS[item.type], CURSE_PERCENT), 0);
92	
93	const quote = ({ items }: QuoteStep): StepResult => {
94	  const policyBase = policyBasePremium(items);
95	  const firstInsurance = percentOf(policyBase, FIRST_INSURANCE_PERCENT);
96	  const total = policyBase + itemSurcharges(items) + firstInsurance + PROCESSING_FEE;
97	
98	  return { premium: Math.ceil(total) };
99	};
100	
101	export const runScenario = (scenario: Scenario): ScenarioResult => ({
102	  // Only quote steps are exercised so far; claim dispatch arrives with its first test.
103	  results: scenario.steps.map((step) => quote(step as QuoteStep)),
104	});
